CustomField.formula:
/* All IDs the same is Parent Network */ IF( AND( texcellency__DefHC_Parent_NetworkID__c = texcellency__DefHC_NetworkID__c, texcellency__DefHC_NetworkID__c = texcellency__DefHC_HospitalID__c ),"IsParentNetworkUltimate",
/* Child Network - Parent Network ID is not Network ID, Network ID = ID */ IF( AND( Not(ISNULL(texcellency__DefHC_Parent_NetworkID__c)), texcellency__DefHC_Parent_NetworkID__c != texcellency__DefHC_NetworkID__c, texcellency__DefHC_NetworkID__c = texcellency__DefHC_HospitalID__c ),"IsNetworkw/Parent",
/* Ultimate Network - No Parent Network ID and Network ID = ID */ IF( AND( ISNULL(texcellency__DefHC_Parent_NetworkID__c), texcellency__DefHC_NetworkID__c = texcellency__DefHC_HospitalID__c ),"IsNetworkUltimate",
/* Hospital with Network */ IF( AND( Not(ISNULL(texcellency__DefHC_NetworkID__c)), texcellency__DefHC_NetworkID__c != texcellency__DefHC_HospitalID__c ),"IsHospitalw/Parent",
/* Hospital No Parent */ IF( AND( ISNULL(texcellency__DefHC_Parent_NetworkID__c), ISNULL(texcellency__DefHC_NetworkID__c ), Not(ISNULL(texcellency__DefHC_HospitalID__c))),"IsHospitalUltimate",
"N/A")))))
